with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'تطوير التوقعات التشغيلية ودمج النماذج وضمان الجودة','دمج النماذج والتحديث السريع والتوقع الاحتمالي والخرائط وبطاقات الأداء ومراقبة التشغيل والتدقيق.',30,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'تطوير التوقعات التشغيلية',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'التوقعات الاحتمالية المتقدمة',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u3 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'تصميم المنتجات الجوية',3,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u4 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'التحقق والتحسين التشغيلي',4,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('multi-model-forecast-blending','دمج مخرجات النماذج العددية في التوقع التشغيلي','مقارنة النماذج ودمجها وإنتاج سيناريو متوازن.','{"blocks":[{"type":"text","text":"تنتج النماذج العددية حلولاً مختلفة بسبب اختلاف الحالة الابتدائية والشبكة والفيزياء والشروط الحدية."},{"type":"text","text":"يبدأ دمج النماذج بمقارنة التوقيت والموقع والشدة والاتساق بين المتغيرات والطبقات."},{"type":"text","text":"قد تستخدم المتوسطات أو الوسيط أو الأوزان الإحصائية لتجميع مخرجات النماذج."},{"type":"text","text":"يجب تقييم النماذج وفق المتغير والمنطقة والفصل والمهلة الزمنية بدلاً من ترتيب ثابت عام."},{"type":"text","text":"قد يخفي المتوسط أحداثاً متطرفة أو مسارات بديلة مهمة، لذلك ينبغي فحص توزيع الأعضاء والسيناريوهات."},{"type":"text","text":"يساعد التحليل الموضوعي للمتنبئ على تفسير الاختلافات وربطها بالرصد والآليات الجوية."},{"type":"text","text":"يجب عدم إعطاء وزن أكبر لنموذج لمجرد أنه أعلى دقة مكانية دون تقييم أدائه الفعلي."},{"type":"text","text":"يمكن دمج المخرجات الاحتمالية مع التحليل السينوبتيكي والرصد الآني لإنتاج توقع قابل للتحديث."},{"type":"text","text":"تحتاج الأوزان إلى بيانات تحقق تاريخية مستقلة ومراجعة دورية عند تغير إصدارات النماذج."},{"type":"text","text":"ينبغي توثيق سبب اختيار السيناريو الأساسي والبدائل ومصادر عدم اليقين."},{"type":"text","text":"مثال: قد تتفق النماذج على منخفض مطري وتختلف في مساره؛ عندها يعرض نطاق المسارات وتأثير كل منها على المناطق."},{"type":"callout","text":"خلاصة: دمج النماذج عملية تقييم وتركيب وليست اختياراً آلياً لأحد المخرجات."}]}',2260,55,'["تمييز مصادر اختلاف النماذج","فهم الدمج الوزني والموضوعي","بناء سيناريو متكامل"]','تطوير التوقعات التشغيلية'),
('model-consensus-and-forecaster-adjustment','التوافق بين النماذج والتعديل الخبروي للمتنبئ','تفسير التوافق والاختلاف وتوثيق التعديلات على المخرجات العددية.','{"blocks":[{"type":"text","text":"يشير توافق النماذج إلى تشابه الحلول في بعض عناصر الحالة، لكنه لا يضمن صحة التوقع."},{"type":"text","text":"قد تتفق النماذج على وجود النظام وتختلف في التوقيت أو المسار أو الشدة أو التوزيع المحلي."},{"type":"text","text":"يقارن المتنبئ المخرجات بالرصد الحديث وبنية الغلاف الجوي والأنماط المناخية والخصائص المحلية."},{"type":"text","text":"قد يبرر ضعف تمثيل التضاريس أو السحب أو التوقيت إجراء تعديل على بعض المخرجات."},{"type":"text","text":"يجب أن يستند التعديل إلى دليل قابل للتوثيق لا إلى تفضيل شخصي غير مفسر."},{"type":"text","text":"تسجل القيمة الأصلية والتعديل والسبب والمصدر والوقت حتى يمكن تقييم القرار لاحقاً."},{"type":"text","text":"قد يكون التعديل الخبروي مفيداً في ظروف محلية متكررة، لكنه قد يضيف انحيازاً إذا لم يراجع."},{"type":"text","text":"تستخدم المقارنات التاريخية لتقييم أداء التعديلات البشرية بحسب المتنبئ والمتغير والمنطقة."},{"type":"text","text":"ينبغي الفصل بين تعديل التوقع بسبب رصد جديد وتعديله بسبب حكم تحليلي على النموذج."},{"type":"text","text":"تراجع القرارات بعد الحدث لمعرفة ما إذا كان التعديل حسّن النتيجة أو زاد الخطأ."},{"type":"text","text":"مثال: إذا أظهر الرادار بدء هطول قبل توقيت النموذج، يمكن تعديل بداية التوقع مع توثيق الدليل."},{"type":"callout","text":"خلاصة: الخبرة البشرية تكمل النماذج عندما تكون منظمة وموثقة وخاضعة للتحقق."}]}',2270,55,'["قراءة توافق النماذج","تحديد أسباب التعديل","توثيق القرار الخبروي"]','تطوير التوقعات التشغيلية'),
('rapid-update-cycling-and-short-range-analysis','التحديث السريع للتحليل والتنبؤ قصير المدى','دورات التهيئة المتكررة ودمج الرصد عالي التواتر.','{"blocks":[{"type":"text","text":"تستخدم أنظمة التحديث السريع دورات متقاربة زمنياً لإدخال المشاهدات الجديدة وتحسين الحالة الابتدائية."},{"type":"text","text":"تستفيد هذه الأنظمة من الرادار والأقمار والمحطات والبرق وبيانات الطائرات عند توافرها."},{"type":"text","text":"تساعد الدورات المتكررة على متابعة تطور الظواهر سريعة التغير مقارنة بدورة نموذج طويلة واحدة."},{"type":"text","text":"يجب التحقق من توقيت البيانات وتأخر وصولها قبل إدخالها في التحليل."},{"type":"text","text":"قد تسبب التغييرات الكبيرة بين الدورات قفزات في التوقع إذا لم يكن التحليل متوازناً زمنياً وديناميكياً."},{"type":"text","text":"تستخدم أساليب استيعاب متتابعة أو رباعية الأبعاد لربط المشاهدات بتطور الحالة."},{"type":"text","text":"تختلف فاعلية التحديث السريع بحسب نوع الظاهرة ومعدل الرصد ودقة النموذج."},{"type":"text","text":"تحتاج المنتجات إلى عرض وقت آخر تحديث والمهلة المتبقية بوضوح."},{"type":"text","text":"قد تكون دقة التوقع القصير عالية مكانياً لكنها حساسة لأخطاء الرصد والتمثيل المحلي."},{"type":"text","text":"يجب تقييم التحليل والتنبؤ بعد كل دورة باستخدام مشاهدات مستقلة قدر الإمكان."},{"type":"text","text":"مثال: إدخال مسح راداري جديد قد يحسن تحديد موقع العاصفة، لكن يجب فحص اتساقه مع المسوح السابقة."},{"type":"callout","text":"خلاصة: التحديث السريع يزيد الاستجابة للظواهر المتغيرة ويتطلب إدارة دقيقة للتوقيت والجودة."}]}',2280,55,'["شرح دورات التحديث السريع","فهم أثر الرصد المتكرر","تقييم استقرار التحليل"]','تطوير التوقعات التشغيلية'),
('probabilistic-precipitation-forecasting','التنبؤ الاحتمالي بالهطول وتجاوز العتبات','تحويل مجموعات النماذج إلى احتمالات مكانية وزمنية للهطول.','{"blocks":[{"type":"text","text":"يعرض التنبؤ الاحتمالي فرصة تجاوز حدث محدد بدلاً من تقديم قيمة مطر وحيدة."},{"type":"text","text":"يجب تحديد العتبة والمدة والمنطقة قبل حساب الاحتمال، مثل تجاوز كمية مطر خلال 24 ساعة."},{"type":"text","text":"يمكن حساب الاحتمال التجميعي من نسبة أعضاء المجموعة التي تتجاوز العتبة، مع مراعاة حجم المجموعة ومعايرتها."},{"type":"text","text":"تختلف الاحتمالات باختلاف مهلة التنبؤ ومقياس المكان وفترة التجميع."},{"type":"text","text":"تساعد خرائط الاحتمالات على تحديد مناطق الخطر النسبي ومجالات عدم اليقين."},{"type":"text","text":"قد تكون المجموعة ناقصة التشتت أو مفرطة التشتت، ولذلك لا تعني النسبة الخام احتمالاً معايراً بالضرورة."},{"type":"text","text":"تستخدم بيانات تحقق تاريخية لتقييم الموثوقية والتمييز ومهارة الاحتمالات."},{"type":"text","text":"تتغير الاحتمالات عند تغيير العتبة أو الفترة، لذلك يجب إظهار التعريف في المنتج."},{"type":"text","text":"قد يتغير احتمال المطر الغزير محلياً بسبب حساسية الحمل والتضاريس ومسار النظام."},{"type":"text","text":"ينبغي عرض الاحتمال مع وصف الشدة والتوقيت وعدم اليقين وليس منفرداً."},{"type":"text","text":"مثال: احتمال 40 بالمئة لتجاوز عتبة مطرية يعني أن الحدث ليس مؤكداً ولا مستبعداً، ويجب ربطه بالتعرض والأثر."},{"type":"callout","text":"خلاصة: التنبؤ الاحتمالي يوضح نطاق النتائج المحتملة ويدعم القرار تحت عدم اليقين."}]}',2290,55,'["تعريف الحدث والعتبة","حساب الاحتمالات من المجموعة","تفسير خرائط الاحتمال"]','التوقعات الاحتمالية المتقدمة'),
('severe-weather-outlook-and-risk-categories','إعداد توقعات الظواهر الشديدة وفئات الخطورة','تحديد البيئات الملائمة للعواصف والرياح والبرد والهطول الشديد.','{"blocks":[{"type":"text","text":"تحدد نظرة الظواهر الشديدة المناطق التي تتوفر فيها بيئة جوية ملائمة لظواهر مثل العواصف والبرد والرياح الشديدة."},{"type":"text","text":"تجمع المؤشرات الديناميكية والحرارية والرطوبية مثل CAPE والقص والرفع والرطوبة العميقة."},{"type":"text","text":"لا يثبت وجود عدم استقرار مرتفع وحده حدوث عاصفة شديدة؛ إذ تحتاج الحالة آلية رفع وتنظيماً مناسباً."},{"type":"text","text":"تختلف المخاطر بين العواصف المنظمة والخلايا المفردة والأنظمة الخطية وفق البيئة الجوية."},{"type":"text","text":"يجب تحديد الاحتمال المكاني والمدة ونوع الظاهرة وفئة الشدة وفق نظام التصنيف المستخدم."},{"type":"text","text":"تستخدم مخرجات النماذج التجميعية لتقدير انتشار السيناريوهات ومجالات الثقة."},{"type":"text","text":"تساعد خرائط الرادار والأقمار والسبر على تحديث النظرة عند اقتراب الحالة."},{"type":"text","text":"قد تتغير مناطق الخطر مع تحديثات النماذج أو تطور النظام، ولذلك تحتاج المنتجات إلى مراجعة دورية."},{"type":"text","text":"ينبغي توضيح أن فئات الخطورة تصف احتمالات أو مستوى خطر وفق تعريف محدد، وليست ضماناً لحدوث الظاهرة."},{"type":"text","text":"تراجع النظرات بعد الحدث بمقارنة التوقع بالمناطق والظواهر المرصودة."},{"type":"text","text":"مثال: بيئة ذات قص قوي ورطوبة وعدم استقرار متوسط قد تدعم عواصف منظمة إذا تحقق الرفع المناسب."},{"type":"callout","text":"خلاصة: توقع الظواهر الشديدة يدمج البيئة واسعة النطاق والتطور الآني والاحتمالات."}]}',2300,55,'["تحليل البيئة الداعمة للظواهر الشديدة","تمييز الاحتمال عن الشدة","إعداد نظرة توقعية متعددة الأيام"]','التوقعات الاحتمالية المتقدمة'),
('forecast-uncertainty-maps-and-scenario-narratives','خرائط عدم اليقين وسرد السيناريوهات الجوية','تمثيل اختلاف النماذج والاحتمالات والسيناريو الأساسي والبدائل.','{"blocks":[{"type":"text","text":"تهدف خرائط عدم اليقين إلى إظهار مدى اختلاف التوقعات أو انتشار أعضاء المجموعة مكانياً وزمنياً."},{"type":"text","text":"يمكن تمثيل الانتشار أو الانحراف المعياري أو احتمالات تجاوز عتبات محددة بحسب المنتج."},{"type":"text","text":"يجب توضيح ما إذا كانت الخريطة تعرض انتشار النماذج أو احتمال الحدث أو ثقة المتنبئ."},{"type":"text","text":"يستخدم السيناريو الأساسي لوصف المسار الأكثر دعماً بالأدلة، بينما توضح السيناريوهات البديلة مسارات أخرى معقولة."},{"type":"text","text":"يجب ربط كل سيناريو بالمؤشرات التي تدعمه وبما قد يؤدي إلى تغيره."},{"type":"text","text":"قد يبدو المتوسط ناعماً ويخفي اختلافاً كبيراً بين الأعضاء، لذلك تعرض خرائط الانتشار عند الحاجة."},{"type":"text","text":"تتغير درجة عدم اليقين بين عناصر الحالة؛ فقد يكون توقيت البداية أوضح من مكان الذروة أو شدتها."},{"type":"text","text":"ينبغي عدم استخدام لون أو تصنيف واحد يوحي بدقة لا تسمح بها البيانات."},{"type":"text","text":"تحتاج الخرائط إلى عنوان ووحدة وفترة ووقت إصدار ومصدر واضح."},{"type":"text","text":"تساعد السرديات الاحتمالية المستخدم على فهم ما هو مرجح وما هو ممكن وما يزال غير محسوم."},{"type":"text","text":"مثال: سيناريو أساسي لمسار منخفض مع بديل شمالي وجنوبي يوضح كيف تتغير مناطق المطر بين الاحتمالات."},{"type":"callout","text":"خلاصة: عرض عدم اليقين الجيد يجعل حدود المعرفة مرئية وقابلة للاستخدام."}]}',2310,55,'["تصميم خريطة عدم يقين","صياغة سيناريوهات بديلة","تجنب الثقة الزائفة"]','التوقعات الاحتمالية المتقدمة'),
('forecast-map-cartography-and-product-design','تصميم خرائط التوقعات الجوية والمنتجات البصرية','اختيار الرموز والألوان والمقاييس وإظهار الزمن والمصدر.','{"blocks":[{"type":"text","text":"تحتاج خريطة التوقع إلى عنوان يحدد المتغير والمنطقة والفترة الزمنية بوضوح."},{"type":"text","text":"يجب أن يتوافق تدرج الألوان مع طبيعة المتغير وأن تكون الفروق قابلة للتمييز."},{"type":"text","text":"تستخدم خطوط تساوي الضغط والارتفاع لعرض الحقول المستمرة، بينما تستخدم الرموز لتمثيل المحطات والظواهر."},{"type":"text","text":"ينبغي أن يوضح مفتاح الخريطة الوحدات والفئات والحدود اللونية دون غموض."},{"type":"text","text":"يجب التمييز بين القيم المرصودة والتوقعات والمنتجات المشتقة بصرياً."},{"type":"text","text":"تؤثر دقة الشبكة والاستيفاء في مظهر الخريطة، ويجب عدم إظهار تفاصيل أدق من البيانات الأصلية."},{"type":"text","text":"تحتاج الخرائط الزمنية إلى بيان وقت الصلاحية والتوقيت العالمي أو المحلي المستخدم."},{"type":"text","text":"ينبغي تجنب ازدحام الخريطة بالرموز والنصوص التي تحجب الأنماط المهمة."},{"type":"text","text":"يجب مراعاة تباين الألوان وإمكانية قراءتها على الشاشات والطباعة."},{"type":"text","text":"تستخدم المقاطع الرأسية والرسوم الزمنية والخرائط الاحتمالية عندما تكون أنسب من الخريطة الثابتة."},{"type":"text","text":"مثال: خريطة تراكم المطر يجب أن توضح فترة التراكم والوحدة ومصدر التوقع ووقت الإصدار."},{"type":"callout","text":"خلاصة: التصميم البصري جزء من جودة المنتج العلمي لأنه يؤثر في فهم البيانات والقرار."}]}',2320,55,'["اختيار تمثيل بصري مناسب","تصميم مفتاح خريطة واضح","إظهار المصدر والوقت والوحدة"]','تصميم المنتجات الجوية'),
('forecast-verification-scorecards','بطاقات تقييم أداء التوقعات ومؤشرات التشغيل','بناء مؤشرات متابعة للنماذج والمنتجات والمهل والمناطق.','{"blocks":[{"type":"text","text":"تلخص بطاقة الأداء جودة التوقعات باستخدام مؤشرات محددة بحسب المتغير والظاهرة والمهلة الزمنية."},{"type":"text","text":"تتضمن المقاييس المستمرة الانحياز وMAE وRMSE والارتباط عند الحاجة."},{"type":"text","text":"تستخدم المقاييس الفئوية مثل POD وFAR وCSI لتقييم الأحداث التي تتجاوز عتبات محددة."},{"type":"text","text":"تستخدم المقاييس الاحتمالية لتقييم الموثوقية والتمييز وجودة التوزيع المتوقع."},{"type":"text","text":"يجب تقسيم النتائج حسب المنطقة والموسم والمهلة ونوع الحدث لتجنب إخفاء مواطن الضعف."},{"type":"text","text":"تحتاج المقارنة إلى عينة كافية وتعريف ثابت للحدث ومصدر مرجعي موثوق."},{"type":"text","text":"قد يؤدي تغيير شبكة الرصد أو تعريف العتبة إلى انقطاع قابلية المقارنة بين الفترات."},{"type":"text","text":"يجب فصل أداء النموذج الخام عن أداء المنتج بعد التعديل البشري أو المعالجة اللاحقة."},{"type":"text","text":"تستخدم الرسوم الزمنية لمراقبة تغير الأداء واكتشاف تدهور مفاجئ أو انحياز موسمي."},{"type":"text","text":"تحدد البطاقة إجراءات تحسين ومسؤوليات ومواعيد مراجعة مرتبطة بالمؤشرات."},{"type":"text","text":"مثال: قد يظهر أداء جيد لمتوسط المطر لكنه ضعيف عند عتبة الهطول الشديد، لذلك تعرض النتائج منفصلة."},{"type":"callout","text":"خلاصة: بطاقة الأداء أداة حوكمة وتحسين وليست مجرد ترتيب للنماذج."}]}',2330,55,'["تصميم بطاقة أداء","اختيار مقاييس مناسبة","مقارنة الأداء عبر الزمن"]','التحقق والتحسين التشغيلي'),
('operational-model-monitoring-and-drift','مراقبة تشغيل النماذج العددية واكتشاف تدهور الأداء','متابعة اكتمال التشغيل وحداثة البيانات والانحياز والانجراف.','{"blocks":[{"type":"text","text":"تحتاج منظومة التنبؤ إلى مراقبة تشغيلية تضمن وصول المدخلات واكتمال الدورات وإنتاج المخرجات في الوقت المحدد."},{"type":"text","text":"تتابع مؤشرات التشغيل وقت بدء الدورة وانتهائها وتوافر الملفات وعدد الحقول وحالة المعالجة."},{"type":"text","text":"يجب التحقق من حداثة البيانات وتوقيت الرصد والوحدات والحقول المطلوبة قبل اعتماد المخرجات."},{"type":"text","text":"قد ينتج فشل التشغيل من انقطاع مصدر البيانات أو أخطاء المعالجة أو نقص الموارد أو تغير صيغة الملفات."},{"type":"text","text":"يستخدم رصد الانحياز ومقاييس التحقق للكشف عن تدهور الأداء عبر الزمن."},{"type":"text","text":"قد يظهر انجراف في البيانات عندما تتغير خصائص المدخلات أو شبكة الرصد أو المناخ عن فترة التقييم السابقة."},{"type":"text","text":"تحتاج الإصدارات الجديدة من النموذج إلى اختبار موازٍ ومقارنة قبل الانتقال التشغيلي الكامل."},{"type":"text","text":"يجب حفظ سجلات التشغيل والأخطاء وإصدارات النماذج والبيانات المستخدمة لإعادة إنتاج النتائج."},{"type":"text","text":"تحدد إجراءات بديلة عند تأخر دورة النموذج أو غياب مصدر مهم، مع تمييز المنتج المتأثر."},{"type":"text","text":"تراجع التنبيهات التشغيلية لتقليل الإنذارات الكاذبة وضمان اكتشاف الأعطال المهمة."},{"type":"text","text":"مثال: تغير عدد المحطات الداخلة في التحليل قد يغير جودة الحالة الابتدائية حتى لو اكتملت دورة النموذج بنجاح."},{"type":"callout","text":"خلاصة: مراقبة النموذج تشمل صحة التشغيل وجودة المدخلات والأداء العلمي واستمرارية الخدمة."}]}',2340,55,'["تحديد مؤشرات تشغيل النموذج","مراقبة جودة المدخلات والمخرجات","اكتشاف الانجراف"]','التحقق والتحسين التشغيلي'),
('forecast-process-audit-and-continuous-improvement','تدقيق دورة التنبؤ والتحسين المستمر','مراجعة إجراءات العمل والبيانات والقرارات والمنتجات ومؤشرات الجودة.','{"blocks":[{"type":"text","text":"يراجع تدقيق دورة التنبؤ جميع المراحل من استلام البيانات حتى إصدار المنتج وحفظه وتقييمه."},{"type":"text","text":"تحدد إجراءات موثقة لكل مرحلة تشمل المسؤوليات والمدخلات والمخرجات ومعايير القبول."},{"type":"text","text":"تفحص سجلات التوقيت والتحديثات ومصادر البيانات والتعديلات البشرية والنسخ المنشورة."},{"type":"text","text":"تسجل حالات عدم المطابقة مثل تأخر المنتج أو نقص البيانات أو استخدام وحدة غير صحيحة أو غموض الرسالة."},{"type":"text","text":"يحدد تحليل السبب الجذري ما إذا كان الخلل ناتجاً عن النظام أو الإجراء أو التدريب أو مصدر البيانات."},{"type":"text","text":"تحدد الإجراءات التصحيحية والوقائية ومسؤوليات التنفيذ والموعد ومؤشر التحقق."},{"type":"text","text":"تحتاج التغييرات في النماذج أو المنتجات أو العتبات إلى مراجعة واعتماد وإصدار موثق."},{"type":"text","text":"تستخدم نتائج التحقق بعد الحالات الجوية لتحديد فرص تحسين عملية التنبؤ."},{"type":"text","text":"تساعد مراجعة المستخدمين والجهات المستفيدة على كشف مشكلات الفهم والتوقيت والتغطية."},{"type":"text","text":"تراجع فاعلية الإجراءات التصحيحية بعد التنفيذ، ولا يكتفى بإغلاق الملاحظة إدارياً."},{"type":"text","text":"مثال: تكرار تأخر التحذير بسبب تأخر بيانات الرادار يستدعي معالجة مصدر البيانات وخطة البديل ومسؤولية المتابعة."},{"type":"callout","text":"خلاصة: التحسين المستمر يحول بيانات الأداء والأخطاء إلى تطوير منظم وقابل للقياس."}]}',2350,55,'["تحديد مراحل التدقيق","توثيق الانحرافات والإجراءات التصحيحية","بناء دورة تحسين مستمرة"]','التحقق والتحسين التشغيلي'))
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case d.unit when 'تطوير التوقعات التشغيلية' then u1.id when 'التوقعات الاحتمالية المتقدمة' then u2.id when 'تصميم المنتجات الجوية' then u3.id when 'التحقق والتحسين التشغيلي' then u4.id end,d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'تطوير التوقعات التشغيلية ودمج النماذج وضمان الجودة',d.unit from d cross join c cross join ch cross join u1 cross join u2 cross join u3 cross join u4
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;